import { test, expect } from '@playwright/test';

test.describe('VQE View', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
    await page.click('button:has-text("VQE")');
  });

  test('renders VQE controls', async ({ page }) => {
    await expect(page.locator('h2:has-text("VQE")')).toBeVisible();
  });

  test('displays molecule selection dropdown', async ({ page }) => {
    const moleculeSelect = page.locator('select');
    if (await moleculeSelect.isVisible()) {
      await moleculeSelect.click();
      await expect(page.locator('option:has-text("H2")')).toBeVisible();
    }
  });

  test('displays execution mode options', async ({ page }) => {
    await expect(page.locator('text=Simulator')).toBeVisible();
  });

  test('runs VQE simulation and displays energy convergence', async ({ page }) => {
    const runButton = page.locator('button:has-text("Run VQE")');
    await runButton.click();

    await expect(page.locator('.result')).toBeVisible({ timeout: 30000 });
  });

  test('shows energy chart after successful run', async ({ page }) => {
    const runButton = page.locator('button:has-text("Run VQE")');
    await runButton.click();

    await expect(page.locator('.result')).toBeVisible({ timeout: 30000 });

    const chart = page.locator('canvas, svg');
    if (await chart.count() > 0) {
      await expect(chart.first()).toBeVisible();
    }
  });

  test('handles VQE runtime errors gracefully', async ({ page }) => {
    const runButton = page.locator('button:has-text("Run VQE")');
    await runButton.click();

    await expect(page.locator('.result, .error')).toBeVisible({ timeout: 30000 });
  });
