def _check_correctness(item: dict, answer: str) -> bool | None:
    """Score correctness: is the expected value present in the model's answer?"""
    ev = _expected_value(item.get("notes", ""))
    if ev is None:
        return None
    return ev in answer

def _extract_cited_ids(answer: str) -> set[int]:
    """Parse Record ID citations from model answer text.
    Handles formats: 'Record 36895', '[Record 36895]', 'record 36895', etc."""
    ids = set()
    for m in re.finditer(r"(?:record|\[record)\s*(\d+)", answer, re.IGNORECASE):
        try:
            ids.add(int(m.group(1)))
        except ValueError:
            pass
    return ids

