test.describe('Backend API Integration', () => {
  test('connects to backend root endpoint', async ({ page }) => {
    const response = await page.request.get('http://localhost:8000/');
    expect(response.status()).toBe(200);

    const data = await response.json();
    expect(data.name).toBe('QuantumPytho API');
    expect(data.endpoints).toContain('/bloch');
    expect(data.endpoints).toContain('/vqe');
    expect(data.endpoints).toContain('/qec/info');
  });

