    const response = await page.request.post('http://localhost:8000/bloch', {
      data: { theta: 1.047, phi: 1.571, shots: 256 },
    });

    expect(response.status()).toBe(200);
    const data = await response.json();
    expect(data.shots).toBe(256);
    expect(data.statevector).toHaveLength(2);
    expect(data.probabilities).toHaveLength(2);
    expect(Math.abs(data.probabilities[0] + data.probabilities[1] - 1.0)).toBeLessThan(1e-9);
  });

  test('QRNG endpoint returns sequence', async ({ page }) => {
    const response = await page.request.get('http://localhost:8000/qrng?num_qubits=4&length=8');

    expect(response.status()).toBe(200);
    const data = await response.json();
    expect(data.sequence).toHaveLength(8);
    expect(data.num_qubits).toBe(4);
    expect(data.length).toBe(8);
  });

  test('Bell pair endpoint returns counts', async ({ page }) => {
    const response = await page.request.get('http://localhost:8000/bell');

    expect(response.status()).toBe(200);
    const data = await response.json();
    expect(data.counts).toBeDefined();
    expect(data.circuit).toBeDefined();
    expect(data.shots).toBeGreaterThan(0);
  });

  test('QEC info endpoint returns code catalog', async ({ page }) => {
    const response = await page.request.get('http://localhost:8000/qec/info');

    expect(response.status()).toBe(200);
    const data = await response.json();
    expect(data.codes.shor.physical_qubits).toBe(9);
    expect(data.codes.steane.physical_qubits).toBe(7);
  });

  test('VQE molecules endpoint returns catalog', async ({ page }) => {
    const response = await page.request.get('http://localhost:8000/vqe/molecules');

    expect(response.status()).toBe(200);
    const data = await response.json();
    expect(data.molecules).toBeDefined();
    expect(Object.keys(data.molecules).length).toBeGreaterThan(0);
  });

  test('Noise profiles endpoint returns profiles or graceful error', async ({ page }) => {
    const response = await page.request.get('http://localhost:8000/noise/profiles');

    expect(response.status()).toBe(200);
    const data = await response.json();
    expect(data.profiles).toBeDefined();

    if (data.profiles.length > 0) {
      expect(data.profile_info).toBeDefined();
    } else {
      expect(data.error).toBeDefined();
    }
  });

  test('DNA circuits endpoint returns list', async ({ page }) => {
    const response = await page.request.get('http://localhost:8000/dna/circuits');

    expect(response.status()).toBe(200);
    const data = await response.json();
    expect(data.circuits).toBeDefined();
    expect(data.description).toContain('DNA');
  });

