"""Serialization helpers for validation benchmark records."""

from __future__ import annotations

import csv
import json
from io import StringIO

from .provenance import ValidationRecord


def validation_records_to_json(records: list[ValidationRecord]) -> str:
    """Serialize validation records to JSON."""
    return json.dumps(
        [record.to_dict() for record in records], indent=2, sort_keys=True
    )


def validation_records_to_csv(records: list[ValidationRecord]) -> str:
    """Serialize validation records to CSV."""
    if not records:
        return ""

    rows = []
    for record in records:
        payload = record.to_dict()
        payload["basis_gates"] = ",".join(record.basis_gates)
        payload["sim_counts"] = json.dumps(record.sim_counts, sort_keys=True)
        payload["hw_counts_raw"] = json.dumps(record.hw_counts_raw, sort_keys=True)
        payload["hw_counts_corrected"] = json.dumps(
            record.hw_counts_corrected, sort_keys=True
        )
        payload["metadata"] = json.dumps(record.metadata, sort_keys=True)
        rows.append(payload)

    buffer = StringIO()
    writer = csv.DictWriter(buffer, fieldnames=list(rows[0].keys()))
    writer.writeheader()
    writer.writerows(rows)
    return buffer.getvalue()


def validation_records_to_markdown(records: list[ValidationRecord]) -> str:
    """Serialize validation records to a compact Markdown summary table."""
    if not records:
        return "No validation records available."

    header = "| Benchmark | Backend | TVD | Match Score | Repeats |\n| --- | --- | ---: | ---: | ---: |"
    lines = [header]
    for record in records:
        match_score = record.metadata.get("match_score", 0.0)
        lines.append(
            f"| {record.benchmark_id} | {record.backend_name} | {record.tvd_raw:.4f} | {match_score:.2f}% | {record.n_repeats} |"
        )
    return "\n".join(lines)

